#include "training_exact_detail.hpp"
#include "military_training_completion_time.hpp"
#include "hanmo/resident_world_api.hpp"
#include <algorithm>
namespace hanmo::resident {using namespace training_exact_detail;namespace {
void registration(const ActionTimeRegistration& r){if(r.action_kind!="military_train"||r.owner_domain!="military"||r.profile_id!="military_action_time"||r.profile_version!=1||r.source_schema!=2||r.mode!=ActionTimeMode::fixed_duration||r.remaining_meaning!=ActionRemainingMeaning::service_estimate||r.shared_gate_kind||!r.retained_wait_phases.empty())fail("ExactMilitaryTrainingRegistrationMismatch");}
void same_proof(const ActionTimeOwnerProof& a,const ActionTimeOwnerProof& b){if(a.action_ref!=b.action_ref||a.action_kind!=b.action_kind||a.actor_id!=b.actor_id||a.participant_actor_ids!=b.participant_actor_ids||a.phase!=b.phase||a.source_schema!=b.source_schema||!same_source(a.original_execution_source,b.original_execution_source)||a.terminal_result_ref!=b.terminal_result_ref)fail("StaleExactTrainingOwnerProof",a.action_ref);}
}
ActionTimeRegistration exact_military_training_registration(){return {"military_train","military","military_action_time",1,2,ActionTimeMode::fixed_duration,ActionRemainingMeaning::service_estimate,{},{}};}
Status NativeMilitaryTrainingActionTimeRead::enumerate_action_time_owners(const ActionTimeRegistration& r,ActionTimeOwnerIdSink& output)const{return status([&]{registration(r);for(const auto& row:state_.dynamic_training_facts.rows()){take(read_action_time_owner(r,row.first));take(output.append(row.first));}});}
Outcome<ActionTimeOwnerProof> NativeMilitaryTrainingActionTimeRead::read_action_time_owner(const ActionTimeRegistration& r,const StableId& id)const{return guard<ActionTimeOwnerProof>([&]{registration(r);bound(common_,military_,context_);const auto& f=fact(state_,id);header(common_,start_ref(id));take(context_.original.validate_training_acceptance(f));if(find(military_.training_facts,id)||f.elapsed_source_ref.action_ref!=id||f.work_binding_ref.action_id!=id||f.work_binding_ref.action_kind!="military_train"||!same_source(f.work_binding_ref.source_owner_ref,start_ref(id)))fail("ExactTrainingOwnerBindingMismatch",id);
 const auto& original_members=f.terms.participants;CheckpointVector<std::string_view> members,empty;members.reserve(original_members.size());for(const auto& member:original_members)members.push_back(member);const auto original_source=SourceRefBuildView{"military","military_training",id};
 ActionTimeOwnerProofBuildView proof{id,"military_train",f.actor_id,{members},original_source,2,MomentOwnerSourceBuildView{original_source,2},ActionTimeOwnerPhase::working,{},{},{},{empty},{}};
 if(f.phase==DynamicMilitaryTrainingPhase::completed){if(!f.completed_at||!f.terminal_source_ref)fail("ExactTrainingActualTerminalRequired",id);if(context_.access.military_training_completion_time_schema==1)take(validate_exact_training_completion_header(common_,military_,state_,f));else if(f.completion_application_source)fail("UnexpectedMilitaryTrainingCompletionTime",id);proof.phase=ActionTimeOwnerPhase::terminal;proof.ended_source=MomentOwnerSourceBuildView{{"military","military_training_completed",id},2};proof.terminal_result_ref=id;}
 else if(f.phase==DynamicMilitaryTrainingPhase::started){const auto* action=common_.action(id);if(!action||action->kind!="military_train"||action->actor_id!=f.actor_id||action->participants!=f.terms.participants||action->start_tick!=f.started_at.half_day_tick)fail("ExactTrainingActualActionRequired",id);proof.phase=ActionTimeOwnerPhase::working;}
 else fail("UnknownExactTrainingPhase",id);return ActionTimeOwnerProof(proof);
});}
Outcome<WorldMoment> NativeMilitaryTrainingActionTimeRead::read_action_time_source(const ElapsedTimeSource& source)const{return guard<WorldMoment>([&]{const auto* owned=std::get_if<MomentOwnerSource>(&source);if(!owned||owned->source_schema!=2||owned->source_ref.domain!="military")fail("ExactTrainingMomentSourceRequired");const auto& ref=owned->source_ref;const auto& f=fact(state_,ref.id);header(common_,start_ref(f.id));if(ref.kind=="military_training")return f.started_at;if(ref.kind=="military_training_completed"&&f.phase==DynamicMilitaryTrainingPhase::completed&&f.completed_at&&f.terminal_source_ref){if(context_.access.military_training_completion_time_schema==1)take(validate_exact_training_completion_header(common_,military_,state_,f));else if(f.completion_application_source)fail("UnexpectedMilitaryTrainingCompletionTime",f.id);return *f.completed_at;}fail("ExactTrainingMomentSourceRequired",ref.id);});}
Status NativeMilitaryTrainingActionTimeRead::validate_fixed_action_sources(const ActionTimeRegistration& r,const ActionTimeOwnerProof& supplied,const ActionElapsedState& entry,const std::vector<FixedServiceTransition>& transitions)const{return status([&]{registration(r);const auto proof=take(read_action_time_owner(r,entry.action_ref));same_proof(proof,supplied);const auto& f=fact(state_,entry.action_ref);take(validate_fact_history(common_,military_,state_,context_,f,entry,true));const bool terminal=f.phase==DynamicMilitaryTrainingPhase::completed;if(transitions.size()!=(terminal?2u:1u))fail("ExactTrainingFixedHistoryMismatch",f.id);
 for(std::size_t index=0;index<transitions.size();++index){const auto& t=transitions[index];if(t.source_schema!=1||t.action_ref!=f.id||t.transition_ordinal!=Integer(index)||t.execution_source_schema!=2||!same_source(t.execution_source_ref,start_ref(f.id)))fail("ExactTrainingFixedSourceMismatch",t.transition_id);
  if(index==0){const auto* cause=std::get_if<FixedOwnerAdopted>(&t.cause);if(t.kind!=FixedTransitionKind::started||t.previous_transition_ref||!cause||cause->owner_source_schema!=2||!same_source(cause->owner_source_ref,start_ref(f.id))||!same_moment(t.occurred_at,f.started_at,context_.budget)||compare(t.credited_at.value,integer(0,context_.budget),context_.budget)||t.input_basis_refs.size()!=1||t.terminal_disposition)fail("ExactTrainingStartHistoryMismatch",f.id);const auto* input=std::get_if<FixedAppliedInput>(&t.input_basis_refs.front());if(!input||input->source_schema!=2||!same_source(input->source_ref,start_ref(f.id)))fail("ExactTrainingInputBasisRequired",f.id);}
  else{const auto* cause=std::get_if<FixedOwnerTerminated>(&t.cause);const auto expected=f.success?FixedTerminalDisposition::completed:f.terminal_code==std::optional<StableId>{"MilitaryTrainingCancelled"}?FixedTerminalDisposition::cancelled:FixedTerminalDisposition::interrupted;if(t.kind!=FixedTransitionKind::terminal||!cause||cause->owner_result_schema!=2||!same_source(cause->owner_result_ref,completed_ref(f.id))||t.previous_transition_ref!=std::optional<StableId>{transitions.front().transition_id}||!same_moment(t.occurred_at,*f.completed_at,context_.budget)||compare(t.credited_at.value,entry.credited_units.value,context_.budget)||t.terminal_disposition!=std::optional<FixedTerminalDisposition>{expected})fail("ExactTrainingTerminalHistoryMismatch",f.id);}
 }
});}
Status NativeMilitaryTrainingActionTimeRead::validate_shared_action_sources(const ActionTimeRegistration&,const ActionTimeOwnerProof&,const SharedWorkElapsedState&)const{return common_failure("ExactTrainingDoesNotOwnSharedWorkGate");}
Outcome<RunStop> NativeMilitaryTrainingActionTimeRead::read_action_continuation_stop(const ActionTimeRegistration& r,const ActionTimeOwnerProof& supplied,const WorldMoment& now)const{return guard<RunStop>([&]{const auto proof=take(read_action_time_owner(r,supplied.action_ref));same_proof(proof,supplied);const auto& f=fact(state_,proof.action_ref);if(f.phase==DynamicMilitaryTrainingPhase::completed)return f.success?RunStop::completed:f.terminal_code==std::optional<StableId>{"MilitaryTrainingCancelled"}?RunStop::cancelled:RunStop::blocked;const auto* entry=find_fixed_elapsed(elapsed_,f.id);if(!entry||take(compare_world_moments(entry->last_settled_at,now,context_.budget))>0)fail("ExactTrainingElapsedRequired",f.id);return RunStop::budget_exhausted;});}
Outcome<OriginalActionRemaining> NativeMilitaryTrainingActionTimeRead::read_original_action_remaining(const ActionTimeRegistration& r,const ActionTimeOwnerProof& supplied,const WorldMoment&)const{return guard<OriginalActionRemaining>([&]()->OriginalActionRemaining{const auto proof=take(read_action_time_owner(r,supplied.action_ref));same_proof(proof,supplied);const auto* entry=find_fixed_elapsed(elapsed_,proof.action_ref);if(!entry)fail("ExactTrainingElapsedRequired",proof.action_ref);return ActualServiceRemaining{ActualServiceRemainingBuildView{proof.phase==ActionTimeOwnerPhase::terminal?HalfDayDuration{}:take(scale_units_to_duration(take(subtract_work_units(entry->required_units,entry->credited_units,context_.budget)),context_.scale.units_per_half_day,context_.budget)),{proof.original_execution_source.domain,proof.original_execution_source.kind,proof.original_execution_source.id},2}};});}
Outcome<StableId> NativeMilitaryTrainingActionTimeRead::read_gate_result_id(const SharedWorkGateResult&)const{return {false,{},common_failure("ExactTrainingDoesNotOwnSharedWorkGate").error};}
Outcome<SharedWorkGateResult> NativeMilitaryTrainingActionTimeRead::read_original_gate_result(const StableId&)const{return {false,{},common_failure("ExactTrainingDoesNotOwnSharedWorkGate").error};}
Status NativeMilitaryTrainingActionTimeRead::validate_original_gate_result(const SharedWorkGateResult&)const{return common_failure("ExactTrainingDoesNotOwnSharedWorkGate");}
}
